int total_energy(int cells[], int n)
{
    int sum = 0;
    int i;
    // sum zero pasun suru kara
    for(i = 0; i < n; i = i + 1)
    {
        sum = sum + *(cells + i); // pratyek cell chi value add kara
    }
    // final sum return kara
    return sum;
}
